from review import card,save,DATE

i='TCS-3339';_,c=card(i);refs=c['references'];refs[0]['locator']='Section 1, formal (min-rank,C)-Graph Recovery problem and contribution (a); Section 2, incidence and GF(2)-rank conventions; Section 3.2, Lemma 27 for fixed arboricity; Section 4, question 1.'
save(i,dict(title='FPT recovery of graph incidence matrices under low-rank binary perturbations',formal='For each fixed graph class C among all simple graphs, forests, trees, connected simple graphs, and graphs of arboricity at most d for each fixed d≥1, is (min-rank,C)-Graph Recovery fixed-parameter tractable in the perturbation rank r? Given an n×m binary matrix M and r≥0, decide whether there exists an n×m graph incidence matrix S with its graph in C such that rank_{F₂}(M+S)≤r. The target is a deterministic running time f_C(r)(n+m+nm+1)^{c_C}, for a total computable function f_C and a constant c_C independent of r,n,m. Each class is a separate instance of the same question; d is fixed with the class, not an additional input parameter.',definitions='F₂={0,1} has addition and multiplication modulo two, so M+S=M−S and the perturbation is L=M+S. rank_{F₂}(L) is the dimension of its column space over F₂, not rank over R. The input explicitly lists all nm bits, the dimensions, and r in binary; r may be capped at min{n,m}. The rows are labeled vertices [n] and the columns are labeled edges [m]. An incidence matrix S of a simple undirected graph has exactly two ones in each column, in distinct rows, and no two columns have the same pair of one-positions. Thus loops and parallel edges are excluded; zero rows represent isolated vertices and remain part of the recovered graph. No row operations, vertex deletion, or change in matrix dimensions is permitted. One may choose which pair of row vertices each column represents, so edge labels impose no geometric order. A forest has no undirected cycle; a tree is connected and acyclic; a connected graph has a path between every two vertices, with the single-vertex graph connected. Arboricity at most d means that the edges can be partitioned into at most d forests. Take n≥1 and m≥0; infeasible column counts have the natural no answer. For each fixed C, the required algorithm is one uniform deterministic Turing program for all M,r, with no error. The cost is worst-case bit time. The exponent and parameter function may depend on C, including the fixed d, but the exponent cannot depend on r. The task asks whether a decomposition exists, without promising that the input was generated by a recoverable graph; producing every possible graph is a different enumeration requirement.',question_type='yes_no',answer_criterion='Prove or refute the FPT assertion for the listed fixed classes, reporting which cases each result covers. A positive result needs an algorithm and computable parameter bound with polynomial exponent independent of r. A negative result must rule out such an algorithm for a specified class, with any complexity assumption stated explicitly. General NP-completeness, an (mn)^{O(r)} bound, or polynomial recovery under a bound on the number of flipped entries does not decide this rank-parameter question.',context_blocks=[dict(title='The perturbation can be dense but low rank',text='The matrix is the sum of graph incidences and a binary error matrix. Low rank limits the dimension of the error patterns, even when many entries differ. Bounding the number of erroneous entries is a different model and has different algorithmic behavior in the source.',citation='primary'),dict(title='The source gives a parameter-dependent exponent',text='For the listed classes, the paper gives algorithms with running time (mn)^{O(r)}. This is polynomial for each fixed rank, but its exponent grows with the parameter. The question asks whether all rank dependence can instead be placed in a multiplicative computable function.',citation='primary'),dict(title='Ordinary hardness leaves the parameter question open',text='The source reports NP-completeness for rank-bounded recovery when r is part of the input. This does not exclude an FPT algorithm: such an algorithm may still have a rapidly growing dependence on r. Its polynomial-time results for Hamming-weight-bounded errors do not answer the rank version either.',citation='primary'),dict(title='A representation problem motivated by perturbed matroids',text='The paper connects recovery to representations of binary matroids as low-rank perturbations of graphic incidence matrices. It also interprets the task as structured binary matrix decomposition, where the sparse component must be the incidence matrix of an actual graph rather than an arbitrary sparse matrix.',citation='primary')],why='Would determine whether the algebraic dimension of incidence errors is a usable algorithmic parameter for recovering graph structure, beyond polynomial algorithms whose exponent grows with that dimension.',references=refs,progress=[dict(date='2020',text='The source gives (mn)^{O(r)} decision algorithms for the listed classes and leaves the FPT improvement open; it separately establishes polynomial-time recovery for several Hamming-weight variants.',citation='primary')],status='source_open',status_note='Read the full problem definition, incidence/rank conventions, fixed-arboricity case and concluding FPT question. Exact-title, parameterized-recovery and later-work searches through 12 September 2026 found no resolution or later version settling the question. Searches are not exhaustive.',model_self_contained=True,requires_context=False,importance=dict(score=c['importance']['score'],method='editorial',reason='A structural low-rank recovery problem linking graph representations, binary matroids and parameterized algorithms. Existing score retained.',assessed_on=DATE),review_note='Recovered the missing low-rank graph-recovery antecedent, enumerated the intended fixed classes and defined binary arithmetic, incidence columns, isolated vertices and all FPT quantifiers. Kept decision separate from enumeration.',working_summary=dict(sentences=['The input is a binary matrix thought of as graph incidences plus a low-rank binary perturbation.','The algorithm must decide whether some incidence matrix of a graph in the specified fixed class differs from it by rank at most r over F₂.','The source has algorithms polynomial for each fixed r, with an exponent that grows with r.','The question asks whether the exponent can be made independent of r, leaving only a computable multiplicative parameter cost.','This concerns rank of the error matrix, not the number of flipped bits, and covers simple graphs, forests, trees, connected graphs and fixed-arboricity graphs.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary'])),notes=['Recovered low-rank incidence-matrix recovery and the complete list of source classes.','Defined GF(2) rank, simple-graph incidence and fixed labeled matrix dimensions.','Specified deterministic effective FPT, the fixed role of arboricity d and separate class outcomes.','Separated rank from Hamming weight and decision from enumeration.'],checked_sources=[refs[0]['url'],'https://drops.dagstuhl.de/entities/document/10.4230/LIPIcs.ESA.2020.50'])
